/**
 * Exo SYRK driver: mirrors PolyBench/C syrk.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"

/* Include the Exo-generated kernel header. */
#include "generated/syrk/syrk.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/*
 * Kernel implementation in Exo.
 *
 * The Exo code below:
 *  - Defines a reference SYRK kernel that matches the original PolyBench
 *    computation (lower-triangular C update).
 *  - Applies a sequence of scheduling transformations to improve:
 *      * Temporal locality on C by fusing the two outer i-loops.
 *      * Spatial locality on C via tiling the j loop in the rank-k update.
 *      * Cache reuse on A and C via tiling the k loop.
 *      * Parallelism across independent rows of C by parallelizing the outer i-loop.
 *  - Renames the scheduled kernel back to `kernel_syrk` so the C driver keeps
 *    the exact same call interface.
 */

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *
from exo.stdlib.scheduling import *

# Reference SYRK kernel, closely mirroring PolyBench's original loops.
# We operate only on the lower-triangular part of C (j <= i).
@proc
def kernel_syrk_ref(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
):
    # Basic sanity: non-negative problem sizes.
    assert n >= 0
    assert m >= 0

    # 1) Scale the lower triangular part of C by beta.
    #    for (i = 0; i < n; i++)
    #      for (j = 0; j <= i; j++)
    #        C[i][j] *= beta;
    for i in seq(0, n):
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

    # 2) Symmetric rank-k update on the lower triangle:
    #    C := C + alpha * A * A^T
    #    for (i = 0; i < n; i++)
    #      for (k = 0; k < m; k++)
    #        for (j = 0; j <= i; j++)
    #          C[i][j] += alpha * A[i][k] * A[j][k];
    #
    # This structure has:
    #  - Good reuse of A[i, k] across all j for a fixed (i, k).
    #  - Strided accesses to A[j, k] as j varies, which we mitigate
    #    later with cache-friendly tiling in j and k.
    for i in seq(0, n):
        for k in seq(0, m):
            for j in seq(0, i + 1):
                C[i, j] += alpha * A[i, k] * A[j, k]


# Start scheduling from the reference kernel.
kernel_syrk_sched = kernel_syrk_ref

# ---------------------------------------------------------------------------
# 1) Fuse the two outer i-loops.
#
#    Before:
#      for i in 0..n-1: scale C[i, *]
#      for i in 0..n-1: rank-k update on C[i, *]
#
#    After:
#      for i in 0..n-1:
#         scale C[i, *]
#         rank-k update on C[i, *]
#
#    This improves temporal locality on C: each row i is scaled and
#    immediately consumed by the rank-k update, reducing the number
#    of full passes over C.
# ---------------------------------------------------------------------------
i0 = kernel_syrk_sched.find_loop("i")
i1 = kernel_syrk_sched.find_loop("i #1")
kernel_syrk_sched = fuse(kernel_syrk_sched, i0, i1)

# ---------------------------------------------------------------------------
# 2) Tile the j-loop inside the rank-k update.
#
#    We tile only the j-loop that is nested under k (the second 'j')
#    to keep working on contiguous chunks of the C row and to improve
#    cache locality when streaming C[i, j].
#
#    The lower-triangular bound j <= i is preserved by the divide_loop
#    primitive (with tail='guard'), which introduces the necessary
#    bounds checks for partial tiles near j = i.
# ---------------------------------------------------------------------------
tile_j = 64  # j-tile size (chosen for cache-friendly row blocks)
kernel_syrk_sched = divide_loop(kernel_syrk_sched, "j #1", tile_j,
                                ("jo", "ji"), tail="guard")

# ---------------------------------------------------------------------------
# 3) Tile the k-loop.
#
#    We split the reduction dimension k into outer (ko) and inner (ki)
#    loops. This helps keep the active subset of A and C in cache
#    while preserving the original iteration order over k (and hence
#    the exact floating-point accumulation order).
# ---------------------------------------------------------------------------
tile_k = 32  # k-tile size for better reuse of A and C
kernel_syrk_sched = divide_loop(kernel_syrk_sched, "k", tile_k,
                                ("ko", "ki"), tail="guard")

# ---------------------------------------------------------------------------
# 4) Parallelize the outermost i-loop.
#
#    Different rows i of C are independent:
#      - Each iteration i only reads A[i, *] and A[j, *] and writes C[i, *].
#      - No iteration writes to C[j, i] (upper triangle), so no cross-row
#        dependencies exist.
#
#    Thus we can safely parallelize across i to exploit multiple cores.
#    This lowers to OpenMP pragmas in the generated C.
# ---------------------------------------------------------------------------
outer_i = kernel_syrk_sched.find_loop("i")
kernel_syrk_sched = parallelize_loop(kernel_syrk_sched, outer_i)

# ---------------------------------------------------------------------------
# 5) Simplify the resulting code to clean up guards and expressions.
# ---------------------------------------------------------------------------
kernel_syrk_sched = simplify(kernel_syrk_sched)

# ---------------------------------------------------------------------------
# 6) Expose the scheduled kernel under the original public name so the
#    C driver keeps the same interface.
# ---------------------------------------------------------------------------
kernel_syrk = rename(kernel_syrk_sched, "kernel_syrk")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /*
   * Run Exo kernel.
   *
   * Exo compiles the procedure
   *   kernel_syrk(n, m, alpha, beta, C[n,n], A[n,m])
   * to a C function with the following signature:
   *
   *   void kernel_syrk(void* ctxt,
   *                    int n, int m,
   *                    DATA_TYPE* alpha,
   *                    DATA_TYPE* beta,
   *                    DATA_TYPE* C,
   *                    DATA_TYPE* A);
   *
   * We therefore pass scalar arguments by address and flatten the
   * 2D PolyBench arrays to 1D DATA_TYPE* buffers.
   */
  kernel_syrk (/*ctxt=*/NULL, n, m,
               (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
               (DATA_TYPE*)POLYBENCH_ARRAY(C),
               (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
