from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline (unscheduled) SYRK kernel operating on the lower triangular
# part of C. This mirrors the PolyBench SYRK semantics:
#
#   C(i,j) = beta * C(i,j) + alpha * sum_k A(i,k) * A(j,k),  for 0 <= j <= i < n
#
# The upper triangular part of C (j > i) is left unchanged.

@proc
def kernel_syrk_unoptimized(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
):
    # Each row i of C is independent of the others: all updates are to
    # C[i, 0..i], and there are no cross-row dependencies.
    for i in seq(0, n):
        # 1) Scale the lower-triangular part of row i by beta.
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

        # 2) Rank-k update: C[i, j] += alpha * A[i, k] * A[j, k]
        #    for all k and for all j in the lower triangle of row i.
        for k in seq(0, m):
