#    (i+1) is not divisible by J_BLOCK.
kernel_syrk_sched = divide_loop(
    kernel_syrk_sched,
    "j",                 # first j-loop (inside the scaling phase)
    J_BLOCK,
    ("jo_s", "ji_s"),
    tail="guard",
)

